Actionscript.script:
var listener = new Object();
listener.click = function (e) {
    trace("clicked " + e.target._name + " " + e.target.label + " " + agree.selected);
};
go.addEventListener("click", listener);
color.addEventListener("change", mx.utils.Delegate.create(this, function (e) {
    trace("color " + e.target.selectedItem.label + " " + e.target.value + " " + this._name);
}));
count.addEventListener("change", function (e) { trace("count " + e.target.value); });
trace("start " + go.label + " " + agree.selected + " " + color.selectedIndex + " " + color.value + " " + who.text +
    " " + count.value + " " + picks.length + " " + Math.round(go.width) + "x" + Math.round(go.height) + " " + big.selected);
picks.addItem("Fourth");
trace("picks " + picks.length + " " + picks.getItemAt(3));
stop();
